// Traduce el webhook de Meta a la respuesta que toca enviar.
// Reproduce el menu de OrquestadorWhatsApp.enviarMenuPrincipal().

const entrada = $input.first().json;
const valor = entrada?.messages ? entrada : entrada?.entry?.[0]?.changes?.[0]?.value;
const mensaje = valor?.messages?.[0];

if (!mensaje) {
  // Acuses de recibo y cambios de estado: no hay nada que contestar.
  return [];
}

const telefono = mensaje.from;
// El id del boton pulsado, si el cliente pulso uno.
const opcion = mensaje.interactive?.button_reply?.id
  ?? mensaje.interactive?.list_reply?.id
  ?? null;

const menuPrincipal = {
  messaging_product: 'whatsapp',
  to: telefono,
  type: 'interactive',
  interactive: {
    type: 'button',
    body: { text: '¡Hola! Soy el asistente de El Patio. ¿Qué deseas hacer?' },
    action: {
      buttons: [
        { type: 'reply', reply: { id: 'menu:pedido',  title: 'Hacer pedido' } },
        { type: 'reply', reply: { id: 'menu:reserva', title: 'Reservar mesa' } },
        { type: 'reply', reply: { id: 'menu:humano',  title: 'Hablar con alguien' } }
      ]
    }
  }
};

const texto = (cuerpo) => ({
  messaging_product: 'whatsapp',
  to: telefono,
  type: 'text',
  text: { body: cuerpo }
});

let respuesta;
switch (opcion) {
  case 'menu:pedido':
    respuesta = texto('Perfecto. Dime qué quieres pedir y te armo la orden.');
    break;
  case 'menu:reserva':
    respuesta = texto('¿Para cuántas personas y a qué hora quieres la mesa?');
    break;
  case 'menu:humano':
    respuesta = texto('Listo, en un momento te atiende alguien del restaurante.');
    break;
  default:
    // Cualquier texto libre abre el menu, igual que hace el backend.
    respuesta = menuPrincipal;
}

return [{ json: respuesta }];
